#!/usr/bin/env node
// Extract the loadable memory image of an ELF binary as {address: uint32} pairs.
// Usage: node extract.js /app/a.out > out.json
'use strict';

const fs = require('fs');

const PIE_LOAD_BASE = 0x400000; // base a loader picks for ET_DYN (position independent) images

function main() {
  const path = process.argv[2];
  if (!path) {
    process.stderr.write('usage: node extract.js <elf-binary>\n');
    process.exit(1);
  }
  const buf = fs.readFileSync(path);

  if (buf.length < 16 || buf[0] !== 0x7f || buf[1] !== 0x45 || buf[2] !== 0x4c || buf[3] !== 0x46) {
    throw new Error('not an ELF file');
  }

  const is64 = buf[4] === 2;
  const little = buf[5] !== 2;

  const u16 = (o) => (little ? buf.readUInt16LE(o) : buf.readUInt16BE(o));
  const u32 = (o) => (little ? buf.readUInt32LE(o) : buf.readUInt32BE(o));
  const u64 = (o) => Number(little ? buf.readBigUInt64LE(o) : buf.readBigUInt64BE(o));
  const addr = (o) => (is64 ? u64(o) : u32(o));

  const eType = u16(16);
  const phoff = is64 ? u64(0x20) : u32(0x1c);
  const phentsize = u16(is64 ? 0x36 : 0x2a);
  const phnum = u16(is64 ? 0x38 : 0x2c);
  const shoff = is64 ? u64(0x28) : u32(0x20);
  const shentsize = u16(is64 ? 0x3a : 0x2e);
  const shnum = u16(is64 ? 0x3c : 0x30);

  const ET_DYN = 3;
  const base = eType === ET_DYN ? PIE_LOAD_BASE : 0;

  // --- program headers: the loadable segments ---
  const PT_LOAD = 1;
  const segments = [];
  for (let i = 0; i < phnum; i++) {
    const p = phoff + i * phentsize;
    if (p + phentsize > buf.length) break;
    const type = u32(p);
    if (type !== PT_LOAD) continue;
    let offset, vaddr, filesz;
    if (is64) {
      offset = u64(p + 0x08);
      vaddr = u64(p + 0x10);
      filesz = u64(p + 0x20);
    } else {
      offset = u32(p + 0x04);
      vaddr = u32(p + 0x08);
      filesz = u32(p + 0x10);
    }
    segments.push({ offset, vaddr, filesz });
  }

  // --- dynamic relocations: those slots are patched at load time, so their
  //     in-file contents are not trustworthy memory values. Skip them. ---
  const skip = new Set(); // byte addresses (already rebased) that must not be reported
  const SHT_RELA = 4;
  const SHT_REL = 9;
  for (let i = 0; i < shnum; i++) {
    const s = shoff + i * shentsize;
    if (!shoff || s + shentsize > buf.length) break;
    const type = u32(s + 4);
    if (type !== SHT_RELA && type !== SHT_REL) continue;
    const off = is64 ? u64(s + 0x18) : u32(s + 0x10);
    const size = is64 ? u64(s + 0x20) : u32(s + 0x14);
    let entsize = is64 ? u64(s + 0x38) : u32(s + 0x24);
    if (!entsize) entsize = type === SHT_RELA ? (is64 ? 24 : 12) : is64 ? 16 : 8;
    const width = is64 ? 8 : 4;
    for (let o = off; o + entsize <= off + size && o + entsize <= buf.length; o += entsize) {
      const target = addr(o) + base;
      for (let k = 0; k < width; k++) skip.add(target + k);
    }
  }

  // --- build the memory image, emitting 32-bit little-endian words ---
  const out = {};
  for (const seg of segments) {
    const words = Math.floor(seg.filesz / 4);
    for (let w = 0; w < words; w++) {
      const fileOff = seg.offset + w * 4;
      if (fileOff + 4 > buf.length) break;
      const a = seg.vaddr + w * 4 + base;
      if (skip.has(a) || skip.has(a + 1) || skip.has(a + 2) || skip.has(a + 3)) continue;
      out[a] = little ? buf.readUInt32LE(fileOff) : buf.readUInt32BE(fileOff);
    }
  }

  const keys = Object.keys(out).sort((x, y) => Number(x) - Number(y));
  const parts = keys.map((k) => JSON.stringify(String(k)) + ':' + out[k]);
  process.stdout.write('{' + parts.join(',') + '}\n');
}

main();

